export default function getBuiltInMixins ({ type, rawOptions = {} }) {
  let bulitInMixins
  if (isReact) {
    bulitInMixins = [
      proxyEventMixin(),
      directiveHelperMixin(),
      styleHelperMixin(),
      refsMixin(),
      i18nMixin(),
      relationsMixin(type),
      pageRouteMixin(type),
      pageScrollMixin(type)
    ]
  } else if (isWeb) {
    bulitInMixins = [
      proxyEventMixin(),
      refsMixin(),
      pageTitleMixin(type),
      pageStatusMixin(type),
      pageScrollMixin(type),
      componentGenericsMixin(type),
      getTabBarMixin(type),
