      if (__mpx_mode__ !== 'ks') {
        // ks methods 不支持 _ 或者 $ 开头的方法名，所以 ks 不走 methods mixin
        enhancedMixins.unshift(renderHelperMixin())
      }
      bulitInMixins = bulitInMixins.concat(enhancedMixins)
    }
  }
  return bulitInMixins.filter(item => item)
}
